mcp:tool.mcp:input-schema:
{
                    "type": "object",
                    "properties": {
                        "firstName": {
                            "type": "string",
                            "description": "Employee first name"
                        },
                        "lastName": {
                            "type": "string",
                            "description": "Employee last name"
                        },
                        "email": {
                            "type": "string",
                            "format": "email",
                            "description": "Employee email address"
                        },
                        "phone": {
                            "type": "string",
                            "pattern": "^[+]?[1-9]\\d{1,14}$",
                            "description": "Employee phone number"
                        },
                        "department": {
                            "type": "string",
                            "enum": ["HR", "IT", "Finance", "Sales", "Marketing", "Operations", "Engineering"],
                            "description": "Department name"
                        },
                        "position": {
                            "type": "string",
                            "description": "Job position/title"
                        },
                        "startDate": {
                            "type": "string",
                            "format": "date",
                            "description": "Start date in YYYY-MM-DD format"
                        },
                        "salary": {
                            "type": "number",
                            "minimum": 0,
                            "description": "Annual salary"
                        },
                        "manager": {
                            "type": "string",
                            "description": "Manager name"
                        },
                        "managerEmail": {
                            "type": "string",
                            "format": "email",
                            "description": "Manager email address"
                        },
                        "companyName": {
                            "type": "string",
                            "description": "Company name"
                        },
                        "assets": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            },
                            "description": "List of assets to allocate (laptop, phone, access-card, etc.)"
                        }
                    },
                    "required": ["firstName", "lastName", "email", "department", "position", "startDate"]
                }

{
                    "type": "object",
                    "properties": {
                        "employeeId": {
                            "type": "string",
                            "description": "Unique employee identifier"
                        },
                        "step": {
                            "type": "string",
                            "enum": [
                                "profile-creation",
                                "asset-allocation", 
                                "welcome-email",
                                "asset-notification",
                                "onboarding-complete"
                            ],
                            "description": "The specific onboarding step to retry"
                        }
                    },
                    "required": ["employeeId", "step"]
                }

{
                    "type": "object",
                    "properties": {
                        "prompt": {
                            "type": "string",
                            "minLength": 10,
                            "maxLength": 1000,
                            "description": "Natural language request for employee onboarding assistance"
                        },
                        "context": {
                            "type": "object",
                            "properties": {
                                "employeeId": {"type": "string"},
                                "department": {"type": "string"},
                                "currentStep": {"type": "string"}
                            },
                            "description": "Optional context to help with reasoning"
                        }
                    },
                    "required": ["prompt"]
                }

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    jsonrpc: "2.0",
    id: payload.id default null,
    error: {
        code: -32603,
        message: "Backend Service Error: " ++ error.description,
        data: {
            httpStatus: vars.httpStatus default "unknown",
            timestamp: now()
        }
    }
}

%dw 2.0
output application/json
---
{
    jsonrpc: "2.0",
    id: payload.id default null,
    error: {
        code: -32603,
        message: "Internal server error",
        data: {
            timestamp: now(),
            requestId: uuid()
        }
    }
}
